from model import Source
from writer import Output, Plan

NAME = "rules"
RULES_FILE = "AGENTS.md"
OWNED = (RULES_FILE,)
HEADER = (
    "# AGENTS.md\n"
    "\n"
    "Generated by `ai/sync-ai.sh` from `ai/rules.md`. Do not edit this file: change `ai/rules.md` and run\n"
    "`ai/sync-ai.sh <agent>`.\n"
    "\n"
)


def render(source: Source) -> Plan:
    files: dict[str, Output] = {}

    if source.rules is not None:
        files[RULES_FILE] = Output((HEADER + source.rules).encode())

    return Plan(agent=NAME, files=files, owned=OWNED)
